(() => {
  'use strict';
  const canvas = document.getElementById('sky');
  const ctx = canvas.getContext('2d');
  const TAU = Math.PI * 2;
  const palettes = [
    ['#ff3158','#ffb000','#fff4a3'],
    ['#35d8ff','#4f7cff','#bf76ff'],
    ['#ff4fd8','#ff7a45','#ffe66d'],
    ['#39f5b2','#4ce0ff','#f4ffff'],
    ['#ffdf62','#ff9f1c','#fff7cf'],
    ['#ff4b4b','#ffffff','#4aa8ff']
  ];
  let width = 0;
  let height = 0;
  let dpr = 1;
  let last = performance.now();
  const start = last;
  const particles = [];
  const rockets = [];
  const flashes = [];
  const haze = [];
  const events = [];
  let eventIndex = 0;
  let simTime = 0;

  const rand = (a, b) => a + Math.random() * (b - a);
  const pick = list => list[(Math.random() * list.length) | 0];

  function resize() {
    dpr = Math.min(1.5, window.devicePixelRatio || 1);
    width = window.innerWidth;
    height = window.innerHeight;
    canvas.width = Math.max(1, Math.floor(width * dpr));
    canvas.height = Math.max(1, Math.floor(height * dpr));
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  }
  resize();
  window.addEventListener('resize', resize);

  function schedule(t, fn) { events.push({t, fn}); }

  function launch(nx, ny, style = 'peony', palette = pick(palettes), scale = 1) {
    const sx = nx == null ? rand(width * .15, width * .85) : width * nx;
    const sy = height + 24;
    const tx = sx + rand(-width * .08, width * .08);
    const ty = height * (ny == null ? rand(.14, .56) : ny);
    rockets.push({
      x: sx, y: sy, px: sx, py: sy, tx, ty,
      age: 0, duration: rand(.72, 1.12),
      color: palette[0], palette, style, scale,
      sparks: []
    });
  }

  function particle(x, y, angle, speed, color, options = {}) {
    if (particles.length > 1500) particles.splice(0, particles.length - 1320);
    const life = options.life ?? rand(1.15, 2.05);
    particles.push({
      x, y, px: x, py: y,
      vx: Math.cos(angle) * speed,
      vy: Math.sin(angle) * speed,
      color,
      age: 0,
      life,
      drag: options.drag ?? .985,
      gravity: options.gravity ?? rand(55, 78),
      size: options.size ?? rand(1.15, 2.25),
      glow: options.glow ?? 12,
      twinkle: options.twinkle ?? Math.random() < .38,
      trail: options.trail ?? true,
      crackle: options.crackle ?? false,
      cracked: false
    });
  }

  function flash(x, y, color, radius = 82) {
    flashes.push({x, y, color, radius, age: 0, life: .32});
    haze.push({x, y, age: 0, life: 2.4, radius: radius * .42});
  }

  function linePoints(out, ax, ay, bx, by, count) {
    for (let i = 0; i < count; i++) {
      const t = count === 1 ? 0 : i / (count - 1);
      out.push({x: ax + (bx - ax) * t, y: ay + (by - ay) * t});
    }
  }

  function buildShape(style) {
    const points = [];

    if (style === 'star') {
      const vertices = [];
      for (let i = 0; i < 10; i++) {
        const angle = -Math.PI / 2 + i * Math.PI / 5;
        const radius = i % 2 === 0 ? 1 : .42;
        vertices.push({x: Math.cos(angle) * radius, y: Math.sin(angle) * radius});
      }
      for (let i = 0; i < vertices.length; i++) {
        const a = vertices[i];
        const b = vertices[(i + 1) % vertices.length];
        linePoints(points, a.x, a.y, b.x, b.y, 7);
      }
      return points;
    }

    if (style === 'heart') {
      for (let i = 0; i < 84; i++) {
        const t = i / 84 * TAU;
        const x = 16 * Math.pow(Math.sin(t), 3) / 18;
        const y = -(13 * Math.cos(t) - 5 * Math.cos(2 * t) - 2 * Math.cos(3 * t) - Math.cos(4 * t)) / 18;
        points.push({x, y});
      }
      return points;
    }

    if (style === 'flower') {
      for (let i = 0; i < 96; i++) {
        const t = i / 96 * TAU;
        const radius = Math.cos(3 * t);
        points.push({x: Math.cos(t) * radius, y: Math.sin(t) * radius});
      }
      for (let i = 0; i < 18; i++) {
        const t = i / 18 * TAU;
        points.push({x: Math.cos(t) * .22, y: Math.sin(t) * .22});
      }
      return points;
    }

    if (style === 'butterfly') {
      for (let i = 0; i < 104; i++) {
        const t = i / 104 * TAU;
        const radius = Math.exp(Math.cos(t)) - 2 * Math.cos(4 * t) + Math.pow(Math.sin(t / 12), 5);
        points.push({x: Math.sin(t) * radius / 4.2, y: -Math.cos(t) * radius / 4.2});
      }
      linePoints(points, 0, -.58, 0, .62, 12);
      return points;
    }

    if (style === 'geometry') {
      for (let ring = 0; ring < 3; ring++) {
        const radius = .38 + ring * .3;
        const rotation = ring * Math.PI / 6;
        const vertices = [];
        for (let i = 0; i < 6; i++) {
          const angle = rotation + i * TAU / 6;
          vertices.push({x: Math.cos(angle) * radius, y: Math.sin(angle) * radius});
        }
        for (let i = 0; i < 6; i++) {
          const a = vertices[i];
          const b = vertices[(i + 1) % 6];
          linePoints(points, a.x, a.y, b.x, b.y, 5);
        }
      }
      for (let i = 0; i < 30; i++) {
        const t = i / 29;
        const angle = t * TAU * 2.4;
        points.push({x: Math.cos(angle) * t * .7, y: Math.sin(angle) * t * .7});
      }
      return points;
    }


    return points;
  }

  function shapeBurst(x, y, style, palette, scale) {
    const points = buildShape(style);
    const spread = 278 * scale;
    for (let i = 0; i < points.length; i++) {
      const point = points[i];
      const vx = point.x * spread;
      const vy = point.y * spread;
      const angle = Math.atan2(vy, vx);
      const speed = Math.hypot(vx, vy);
      particle(x, y, angle, speed, palette[i % palette.length], {
        life: rand(2.25, 2.85),
        gravity: 18,
        drag: .995,
        size: rand(1.45, 2.25),
        twinkle: i % 3 === 0
      });
      if (i % 2 === 0) {
        particle(x, y, angle, speed * .68, palette[(i + 1) % palette.length], {
          life: rand(1.85, 2.35),
          gravity: 17,
          drag: .994,
          size: rand(1.0, 1.55),
          twinkle: true
        });
      }
    }
    for (let i = 0; i < 28; i++) {
      particle(x, y, rand(0, TAU), rand(48, 145) * scale, i % 4 === 0 ? "#ffffff" : pick(palette), {
        life: rand(.85, 1.45),
        gravity: 34,
        drag: .982,
        size: rand(.8, 1.35),
        trail: false,
        twinkle: true
      });
    }
  }

  function explode(x, y, style, palette, scale = 1) {
    const base = Math.min(width, height) / 900;
    const s = scale * Math.max(.72, Math.min(1.35, base));
    flash(x, y, palette[0], 88 * scale);

    if (["star", "heart", "flower", "butterfly", "geometry"].includes(style)) {
      shapeBurst(x, y, style, palette, s);
      return;
    }

    if (style === "willow") {
      for (let i = 0; i < 56; i++) {
        const a = (i / 56) * TAU + rand(-.025, .025);
        const speed = rand(105, 245) * s * (.72 + .28 * Math.sin(a) ** 2);
        particle(x, y, a, speed, pick(['#ffd45a','#ffec9a','#fff8d1']), {
          life: rand(2.5, 3.6), gravity: rand(42, 58), drag: .988,
          size: rand(1.3, 2.5), glow: 15, twinkle: true
        });
      }
      return;
    }

    if (style === 'ring') {
      const count = 64;
      for (let i = 0; i < count; i++) {
        const a = i / count * TAU;
        particle(x, y, a, rand(210, 226) * s, palette[i % palette.length], {
          life: rand(1.55, 2.05), gravity: 48, drag: .989, size: 2.05, glow: 15
        });
      }
      for (let i = 0; i < 18; i++) {
        const a = rand(0, TAU);
        particle(x, y, a, rand(65, 155) * s, '#ffffff', {life: rand(.8, 1.25), gravity: 65, size: 1.4});
      }
      return;
    }

    if (style === 'palm') {
      for (let i = 0; i < 18; i++) {
        const a = -Math.PI + (i / 17) * Math.PI + rand(-.08, .08);
        particle(x, y, a, rand(160, 315) * s, pick(palette), {
          life: rand(2.1, 3.0), gravity: rand(75, 105), drag: .982,
          size: rand(2.0, 3.2), glow: 18, twinkle: true, crackle: i % 3 === 0
        });
      }
      for (let i = 0; i < 36; i++) {
        const a = rand(0, TAU);
        particle(x, y, a, rand(55, 145) * s, '#ffd56a', {life: rand(.85, 1.4), gravity: 70, size: 1.4});
      }
      return;
    }

    if (style === 'crackle') {
      for (let i = 0; i < 56; i++) {
        const a = rand(0, TAU);
        const speed = Math.sqrt(Math.random()) * 265 * s;
        particle(x, y, a, speed, pick(palette), {
          life: rand(1.25, 1.9), gravity: 72, drag: .981,
          size: rand(1.4, 2.35), glow: 14, crackle: true
        });
      }
      return;
    }

    const count = style === "chrysanthemum" ? 92 : 72;
    for (let i = 0; i < count; i++) {
      const a = (i / count) * TAU + rand(-.035, .035);
      const speed = rand(118, style === 'chrysanthemum' ? 310 : 275) * s;
      particle(x, y, a, speed, pick(palette), {
        life: rand(1.55, 2.45), gravity: rand(55, 78),
        drag: style === 'chrysanthemum' ? .986 : .982,
        size: rand(1.25, 2.35), glow: 14,
        twinkle: style === 'chrysanthemum' || Math.random() < .4
      });
    }
  }

  function crackleAt(p) {
    const color = Math.random() < .55 ? '#fff4bd' : '#ffffff';
    for (let i = 0; i < 4; i++) {
      particle(p.x, p.y, rand(0, TAU), rand(24, 90), color, {
        life: rand(.28, .58), gravity: 48, drag: .94,
        size: rand(.75, 1.45), glow: 9, trail: false, twinkle: true
      });
    }
  }

  function updateRocket(r, dt) {
    r.age += dt;
    r.px = r.x;
    r.py = r.y;
    const t = Math.min(1, r.age / r.duration);
    const eased = 1 - Math.pow(1 - t, 2.15);
    r.x = r.x + (r.tx - r.x) * Math.min(1, dt * 3.7);
    r.y = height + 24 + (r.ty - height - 24) * eased;
    r.sparks.push({x: r.x + rand(-1.4, 1.4), y: r.y + rand(1, 8), age: 0, life: rand(.18, .42)});
    if (r.sparks.length > 18) r.sparks.shift();
    for (const s of r.sparks) s.age += dt;
    r.sparks = r.sparks.filter(s => s.age < s.life);
    if (t >= 1) {
      explode(r.x, r.y, r.style, r.palette, r.scale);
      return false;
    }
    return true;
  }

  function drawRocket(r) {
    ctx.save();
    ctx.globalCompositeOperation = 'lighter';
    const grad = ctx.createLinearGradient(r.px, r.py + 18, r.x, r.y);
    grad.addColorStop(0, 'rgba(255,170,50,0)');
    grad.addColorStop(1, '#ffffff');
    ctx.strokeStyle = grad;
    ctx.lineWidth = 2.2;
    ctx.shadowBlur = 14;
    ctx.shadowColor = r.color;
    ctx.beginPath();
    ctx.moveTo(r.px, r.py + 18);
    ctx.lineTo(r.x, r.y);
    ctx.stroke();
    for (const s of r.sparks) {
      const alpha = 1 - s.age / s.life;
      ctx.globalAlpha = alpha;
      ctx.fillStyle = Math.random() < .5 ? '#fff4bb' : '#ff9f35';
      ctx.fillRect(s.x, s.y, rand(.8, 1.8), rand(2, 5));
    }
    ctx.restore();
  }

  function updateParticle(p, dt) {
    p.age += dt;
    if (p.age >= p.life) return false;
    p.px = p.x;
    p.py = p.y;
    p.vx *= Math.pow(p.drag, dt * 60);
    p.vy = p.vy * Math.pow(p.drag, dt * 60) + p.gravity * dt;
    p.x += p.vx * dt;
    p.y += p.vy * dt;
    if (p.crackle && !p.cracked && p.age > p.life * .72) {
      p.cracked = true;
      crackleAt(p);
    }
    return p.y < height + 80;
  }

  function drawParticle(p) {
    const left = 1 - p.age / p.life;
    const alpha = Math.min(1, left * 2.7) * (p.twinkle ? rand(.5, 1) : 1);
    ctx.globalAlpha = alpha;
    ctx.strokeStyle = p.color;
    ctx.fillStyle = p.color;
    if (p.trail) {
      ctx.lineWidth = Math.max(.65, p.size * left);
      ctx.beginPath();
      ctx.moveTo(p.px, p.py);
      ctx.lineTo(p.x, p.y);
      ctx.stroke();
    }
    const size = Math.max(.7, p.size * (.55 + left * .45));
    ctx.fillRect(p.x - size * .5, p.y - size * .5, size, size);
  }

  function drawFlash(f) {
    const t = f.age / f.life;
    const g = ctx.createRadialGradient(f.x, f.y, 0, f.x, f.y, f.radius * (1 + t * .65));
    g.addColorStop(0, `rgba(255,255,255,${.48 * (1 - t)})`);
    g.addColorStop(.18, f.color);
    g.addColorStop(1, 'rgba(255,255,255,0)');
    ctx.save();
    ctx.globalCompositeOperation = 'lighter';
    ctx.globalAlpha = (1 - t) * .7;
    ctx.fillStyle = g;
    ctx.fillRect(f.x - f.radius * 2, f.y - f.radius * 2, f.radius * 4, f.radius * 4);
    ctx.restore();
  }

  function drawHaze(h) {
    const t = h.age / h.life;
    const radius = h.radius * (1 + t * 1.8);
    const alpha = Math.sin(Math.PI * t) * .045;
    const cx = h.x + t * 24;
    const cy = h.y + t * 18;
    const g = ctx.createRadialGradient(cx, cy, 0, cx, cy, radius);
    g.addColorStop(0, "rgba(180,190,220," + alpha + ")");
    g.addColorStop(.55, "rgba(180,190,220," + alpha * .28 + ")");
    g.addColorStop(1, "rgba(180,190,220,0)");
    ctx.save();
    ctx.fillStyle = g;
    ctx.beginPath();
    ctx.arc(cx, cy, radius, 0, TAU);
    ctx.fill();
    ctx.restore();
  }

  schedule(.10, () => launch(.22, .38, 'peony', palettes[0], .72));
  schedule(.42, () => launch(.73, .28, 'star', palettes[4], .92));
  schedule(1.02, () => launch(.47, .20, 'flower', palettes[2], .94));
  schedule(1.68, () => launch(.18, .31, 'butterfly', palettes[1], .86));
  schedule(2.25, () => launch(.81, .31, 'heart', palettes[0], .86));
  schedule(3.00, () => launch(.50, .17, 'geometry', palettes[3], 1.0));
  schedule(3.82, () => launch(.27, .24, 'flower', palettes[5], .90));
  schedule(4.40, () => launch(.73, .28, 'palm', palettes[4], .82));
  schedule(5.14, () => {
    launch(.19, .23, 'flower', palettes[3], .76);
    launch(.82, .24, 'butterfly', palettes[2], .76);
  });
  schedule(6.12, () => launch(.50, .14, 'willow', palettes[4], 1.08));
  schedule(7.00, () => {
    launch(.20, .30, 'star', palettes[1], .74);
    launch(.50, .18, 'heart', palettes[0], .86);
    launch(.80, .30, 'geometry', palettes[3], .74);
  });
  schedule(8.00, () => {
    launch(.15, .34, 'flower', palettes[2], .72);
    launch(.34, .22, 'crackle', palettes[4], .76);
    launch(.50, .13, 'geometry', palettes[5], .96);
    launch(.67, .22, 'chrysanthemum', palettes[1], .76);
    launch(.85, .34, 'butterfly', palettes[3], .72);
  });
  schedule(8.76, () => {
    launch(.26, .19, 'willow', palettes[4], .88);
    launch(.50, .10, 'flower', palettes[0], 1.02);
    launch(.74, .19, 'willow', palettes[4], .88);
  });

  events.sort((a,b) => a.t - b.t);

  function advance(dt) {
    for (let i = haze.length - 1; i >= 0; i--) {
      haze[i].age += dt;
      if (haze[i].age >= haze[i].life) haze.splice(i, 1);
    }
    for (let i = rockets.length - 1; i >= 0; i--) {
      if (!updateRocket(rockets[i], dt)) rockets.splice(i, 1);
    }
    for (let i = particles.length - 1; i >= 0; i--) {
      if (!updateParticle(particles[i], dt)) particles.splice(i, 1);
    }
    for (let i = flashes.length - 1; i >= 0; i--) {
      flashes[i].age += dt;
      if (flashes[i].age >= flashes[i].life) flashes.splice(i, 1);
    }
  }

  function frame(now) {
    const elapsed = Math.min(10, (now - start) / 1000);
    while (simTime < elapsed) {
      const dt = Math.min(.034, elapsed - simTime);
      simTime += dt;
      while (eventIndex < events.length && simTime >= events[eventIndex].t) events[eventIndex++].fn();
      advance(dt);
    }

    ctx.clearRect(0, 0, width, height);
    const night = ctx.createLinearGradient(0, 0, 0, height);
    night.addColorStop(0, "rgba(3,4,18,.16)");
    night.addColorStop(1, "rgba(0,0,5,.04)");
    ctx.fillStyle = night;
    ctx.fillRect(0, 0, width, height);

    for (const item of haze) drawHaze(item);
    for (const item of rockets) drawRocket(item);
    ctx.save();
    ctx.globalCompositeOperation = "lighter";
    for (const item of particles) drawParticle(item);
    ctx.restore();
    for (const item of flashes) drawFlash(item);

    if (elapsed >= 10) { clearInterval(timer); notchany.finish(); }
  }
  const timer = setInterval(() => frame(performance.now()), 20);
  frame(performance.now());
})();
